			/**
			* Sets the font line style of the given range ('underline', 'line-through', or 'none').
			* @param {FontLine|null} fontLine The font line style, either 'underline', 'line-through', or 'none'; a null value resets the font line style.
			* @returns {FRange} This range, for chaining
			* @example
			* ```ts
			* const fWorkbook = univerAPI.getActiveWorkbook();
			* const fWorksheet = fWorkbook.getSheetByName('Sheet1');
			* if (!fWorksheet) return;
			* const fRange = fWorksheet.getRange('A1:B2');
			* fRange.setFontLine('underline');
			* ```
			*/
			setFontLine(fontLine) {
				if (fontLine === "underline") this._setFontUnderline({ s: BooleanNumber.TRUE });
				else if (fontLine === "line-through") this._setFontStrikethrough({ s: BooleanNumber.TRUE });
				else if (fontLine === "none") {
					this._setFontUnderline({ s: BooleanNumber.FALSE });
					this._setFontStrikethrough({ s: BooleanNumber.FALSE });
				} else if (fontLine === null) {
					this._setFontUnderline(null);
					this._setFontStrikethrough(null);
				} else throw new Error("Invalid fontLine");
				return this;
			}
